    'FieldRoutes availability was unavailable, so no slots were proposed. Call back to book.',
    `Lead: ${leadRef(ctx)}`,
    `HubSpot contact (phone and email are here): ${contactLink(ctx.settings, ctx.hubspot.contact_id)}`,
